// JudgeChild refuses a running child unless its session is a state of the
// document it names, to any depth (sce.SavedPolicy).
func (p *StaticInvokeOptionalPolicy) JudgeChild(child sce.SavedChild) error {
	switch {
	case child.ID == "given" && child.Document == "static_invoke_optional__sce_synth_invoke__given":
		return StaticInvokeOptionalSceSynthInvokeGivenJudge(child.Session)
	case child.ID == "lifted" && child.Document == "static_invoke_optional__sce_synth_invoke__lifted":
		return StaticInvokeOptionalSceSynthInvokeLiftedJudge(child.Session)
	case child.ID == "absent" && child.Document == "static_invoke_optional__sce_synth_invoke__absent":
		return StaticInvokeOptionalSceSynthInvokeAbsentJudge(child.Session)
	case child.ID == "replaced" && child.Document == "static_invoke_optional__sce_synth_invoke__replaced":
		return StaticInvokeOptionalSceSynthInvokeReplacedJudge(child.Session)
	case child.ID == "over" && child.Document == "static_invoke_optional__sce_synth_invoke__over":
		return StaticInvokeOptionalSceSynthInvokeOverJudge(child.Session)
	case child.ID == "fits" && child.Document == "static_invoke_optional__sce_synth_invoke__fits":
		return StaticInvokeOptionalSceSynthInvokeFitsJudge(child.Session)
	}
	return sce.Refuse(fmt.Sprintf("invokes names '%s' running '%s', a document that `<invoke>` does not start", child.ID, child.Document))
}

// ResumeChildren resumes each of children in the order given, each built as
// starting it builds it and restored where it stood (sce.SavedPolicy).
func (p *StaticInvokeOptionalPolicy) ResumeChildren(engine *sce.Engine[StaticInvokeOptionalState, StaticInvokeOptionalEvent], children []sce.SavedChild, wallNowMs int64) error {
	for _, child := range children {
		var err error
		switch {
		case child.ID == "given" && child.Document == "static_invoke_optional__sce_synth_invoke__given":
			err = p.resumeChildGiven(engine, child, wallNowMs)
		case child.ID == "lifted" && child.Document == "static_invoke_optional__sce_synth_invoke__lifted":
			err = p.resumeChildLifted(engine, child, wallNowMs)
		case child.ID == "absent" && child.Document == "static_invoke_optional__sce_synth_invoke__absent":
			err = p.resumeChildAbsent(engine, child, wallNowMs)
		case child.ID == "replaced" && child.Document == "static_invoke_optional__sce_synth_invoke__replaced":
			err = p.resumeChildReplaced(engine, child, wallNowMs)
		case child.ID == "over" && child.Document == "static_invoke_optional__sce_synth_invoke__over":
			err = p.resumeChildOver(engine, child, wallNowMs)
		case child.ID == "fits" && child.Document == "static_invoke_optional__sce_synth_invoke__fits":
			err = p.resumeChildFits(engine, child, wallNowMs)
		default:
			err = sce.Refuse(fmt.Sprintf("invokes names '%s' running '%s', a document that `<invoke>` does not start", child.ID, child.Document))
		}
		if err != nil {
			return err
		}
	}
	return nil
}

