type StaticInvokeOptionalPolicy struct {
	// W3C SCXML 5.10: Session ID
	SessionID string
	// ── SCE Accepted Subset §2.15: the datamodel="sce-static" variables ──
	// W3C SCXML 5.2: the `size` datamodel variable.
	vSize optional.Of[int32]
	// W3C SCXML 5.2: the `label` datamodel variable.
	vLabel optional.Of[string]
	// W3C SCXML 5.2: the `nosize` datamodel variable.
	vNosize optional.Of[int32]
	// W3C SCXML 5.2: the `lengthy` datamodel variable.
	vLengthy string
	// W3C SCXML 5.2: the `completed` datamodel variable, published (`sce:direction="out"`).
	vCompleted uint32
	// W3C SCXML 5.2: the `errors` datamodel variable, published (`sce:direction="out"`).
	vErrors uint32
	pendingInvokes []sce.PendingInvoke[StaticInvokeOptionalState]
	activeInvokes  map[string]*sce.ChildSession
	childGiven sce.ChildEngine
	pendingDoneInvokeGiven bool
	childLifted sce.ChildEngine
	pendingDoneInvokeLifted bool
	childAbsent sce.ChildEngine
	pendingDoneInvokeAbsent bool
	childReplaced sce.ChildEngine
	pendingDoneInvokeReplaced bool
	childOver sce.ChildEngine
	pendingDoneInvokeOver bool
	childFits sce.ChildEngine
	pendingDoneInvokeFits bool
	// docs/adr/0045: how many times 'given' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsGiven uint64
	// docs/adr/0045: how many times 'lifted' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsLifted uint64
	// docs/adr/0045: how many times 'absent' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsAbsent uint64
	// docs/adr/0045: how many times 'replaced' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsReplaced uint64
	// docs/adr/0045: how many times 'over' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsOver uint64
	// docs/adr/0045: how many times 'fits' has started in
	// this session; the next start, and the id it is started under, is numbered
	// by it, so a child's ids come from the tree alone.
	invokeStartsFits uint64
	// W3C SCXML 6.4: Parent communication (unbounded — see sce.ParentEventQueue)
	ParentExternalQueue *sce.ParentEventQueue
	InvokeID           string
	ChildSessionID     string
	// §scxml-6.4.3: invoke param VALUES staged by the parent, applied after
	// this machine's datamodel init so they override its `<data>` defaults.
	pendingParams      map[string]interface{}
}

// NewStaticInvokeOptionalPolicy creates a new policy with default values.
func NewStaticInvokeOptionalPolicy() StaticInvokeOptionalPolicy {
	return StaticInvokeOptionalPolicy{
		// docs/adr/0045: a session has an id, which a saved state names it by. A
		// host that has one for it gives it with SetSessionID before it starts the
		// machine; a child's is its parent's and the id it was started under.
		SessionID: sce.DrawSessionID(),
		vSize: optional.Some[int32](7),
		vLabel: optional.Some[string]("abc"),
		vNosize: optional.None[int32](),
		vLengthy: "abcdefgh",
		vCompleted: 0,
		vErrors: 0,
		pendingInvokes: make([]sce.PendingInvoke[StaticInvokeOptionalState], 0),
		activeInvokes:  make(map[string]*sce.ChildSession),
	}
}

// Completed reports what the published `completed` datamodel
// variable holds now (W3C SCXML 5.2). Only the machine writes it.
func (p *StaticInvokeOptionalPolicy) Completed() uint32 {
	return p.vCompleted
}

// Errors reports what the published `errors` datamodel
// variable holds now (W3C SCXML 5.2). Only the machine writes it.
func (p *StaticInvokeOptionalPolicy) Errors() uint32 {
	return p.vErrors
}

// StaticInvokeOptionalInvokeParams holds the values a parent's `<param>` and
// `namelist` give this machine's variables before it starts (§scxml-6.4.1). A
// variable left nil, or absent for an optional one, keeps the value its `<data>`
// gave it.
type StaticInvokeOptionalInvokeParams struct {
	VSize optional.Of[int32]
	VLabel optional.Of[string]
	VNosize optional.Of[int32]
	VLengthy *string
	VCompleted *uint32
	VErrors *uint32
}

// AcceptParams gives this machine the values params carries, in place of the
// ones its `<data>` gave. Called before it initializes (§scxml-6.4.1).
func (p *StaticInvokeOptionalPolicy) AcceptParams(params StaticInvokeOptionalInvokeParams) {
	if params.VSize.IsPresent() {
		p.vSize = params.VSize
	}
	if params.VLabel.IsPresent() {
		p.vLabel = params.VLabel
	}
	if params.VNosize.IsPresent() {
		p.vNosize = params.VNosize
	}
	if params.VLengthy != nil {
		p.vLengthy = *params.VLengthy
	}
	if params.VCompleted != nil {
		p.vCompleted = *params.VCompleted
	}
	if params.VErrors != nil {
		p.vErrors = *params.VErrors
	}
}



